### Cross validation ####import pandas as pdimport numpy as npfrom sklearn.metrics import mutual_info_scorefrom collections import Counterfrom tqdm import tqdmfrom scipy.io import mmread expression_matrix = mmread("/Users/ggraham/MERFISH/2025_10_06_genes_meeting_criteria.mtx")""" here, rows are genes (unlabeled) and columns are cells,all of the genes listed here are marker genes that fit Duncans criteriato save computation"""expression_matrix = pd.DataFrame(expression_matrix.toarray())"convert to a dataframe"genes = pd.read_csv("/Users/ggraham/MERFISH/2025_10_06_sparse_mat_rownames.csv")genes = genes['x']"""genes corresponds to the genes (rows) in expression matrix"""clusters = pd.read_csv("/Users/ggraham/MERFISH/2025_10_14_clusters.csv") #changing this from the previous file"""clusters['clusters'] corresponds to the cluster label for each cell"""# Set up data structure like the originalexpression_matrix.index = genes  # Set gene names as index# Create labels dataframe - make sure cell names match expression matrix columnscell_names = expression_matrix.columns df_labels = pd.DataFrame({    'label': clusters['clusters'].values,    'cell_label': cell_names}, index=cell_names)#read in  marker genesmarkersCSV =pd.read_csv("/Users/ggraham/Desktop/multiome_poa/MERFISH/2025_10_14 NS_MI_genes.csv")genes = markersCSV['gene']## machine learning time babeyfrom sklearn.model_selection import cross_val_score, StratifiedKFoldfrom sklearn.ensemble import RandomForestClassifierfrom sklearn.metrics import accuracy_scoreimport numpy as np    #pval # Prepare data - transpose so cells are rows, genes are columnsX = expression_matrix.loc[genes].Ty = df_labels['label']# Initialize classifierclf = RandomForestClassifier(n_estimators=100, random_state=42)# Perform cross-validationcv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)cv_scores = cross_val_score(clf, X, y, cv=cv, scoring='accuracy')# Calculate metricsnp.mean(cv_scores)np.std(cv_scores)###### Confusionfrom sklearn.model_selection import StratifiedKFoldfrom sklearn.ensemble import RandomForestClassifierfrom sklearn.metrics import confusion_matriximport numpy as npimport pandas as pdimport seaborn as snsimport matplotlib.pyplot as plt# --- Set up CV ---cv = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)clf = RandomForestClassifier(n_estimators=100, random_state=42)# --- Store cumulative confusion matrix ---unique_labels = np.sort(np.unique(y))n_labels = len(unique_labels)cumulative_cm = np.zeros((n_labels, n_labels), dtype=int)# --- Loop through CV folds ---for train_idx, test_idx in cv.split(X, y):    X_train, X_test = X.iloc[train_idx], X.iloc[test_idx]    y_train, y_test = y.iloc[train_idx], y.iloc[test_idx]        clf.fit(X_train, y_train)    y_pred = clf.predict(X_test)        cm = confusion_matrix(y_test, y_pred, labels=unique_labels)    cumulative_cm += cm# --- Average confusion matrix over folds (optional) ---avg_cm = cumulative_cm / cv.get_n_splits()# --- Convert to DataFrame for better readability ---cm_df = pd.DataFrame(avg_cm, index=unique_labels, columns=unique_labels)print("Confusion Matrix (rows = true clusters, columns = predicted clusters):")print(cm_df)cm_df = cm_df.div(cm_df.sum(axis=1), axis=0)  # row-normalize# --- Visualize heatmap ---plt.figure(figsize=(10, 8))sns.heatmap(cm_df, annot=True, fmt=".1f", cmap="Blues")plt.xlabel("Predicted Cluster")plt.ylabel("True Cluster")plt.title("Cross-Validated Confusion Matrix")plt.tight_layout()plt.show()